class Cache:
    def __init__(self):
        self.data = {}  # key -> (value, expiry_time)

    def put(self, key, value, now, ttl):
        if ttl <= 0:
            # Expires immediately, so don't store it
            if key in self.data:
                del self.data[key]
            return
        expiry = now + ttl
        self.data[key] = (value, expiry)

    def get(self, key, now):
        if key not in self.data:
            return None
        value, expiry = self.data[key]
        if now >= expiry:
            # Expired
            del self.data[key]
            return None
        return value
